"""Tests for measurement integrity and timing mode preservation."""

from voicebench.adapters.mock import LocalMockAdapter
from voicebench.evaluator import Evaluator
from voicebench.models import ConversationTrace, EventType, TestStatus, TraceEvent
from voicebench.parser import load_scenario_from_file
from pathlib import Path

SCENARIOS_DIR = Path(__file__).parent.parent / "scenarios" / "roundtable"


def test_simulated_events_explicitly_tagged():
    """Verify that events generated by LocalMockAdapter are tagged is_simulated=True."""
    scenario = load_scenario_from_file(SCENARIOS_DIR / "SCEN-ROUT-01.yaml")
    adapter = LocalMockAdapter(target_config="baseline")
    trace = adapter.execute_scenario(scenario)

    for ev in trace.events:
        assert ev.is_simulated is True, f"Event {ev.event_type} must be labeled as simulated"

    evaluator = Evaluator()
    result = evaluator.evaluate(scenario, trace, target_type="local_mock")
    assert result.timing_mode == "virtual_simulation"


def test_unavailable_metrics_are_none_not_zero():
    """Verify that unmeasured metrics default to None and are not converted to 0.0."""
    scenario = load_scenario_from_file(SCENARIOS_DIR / "SCEN-ROUT-01.yaml")
    adapter = LocalMockAdapter(target_config="baseline")
    trace = adapter.execute_scenario(scenario)

    evaluator = Evaluator()
    result = evaluator.evaluate(scenario, trace)

    # In SCEN-ROUT-01, barge-in yield latency and cross-talk overlap are unmeasured
    assert result.metrics["yield_latency_ms"] is None
    assert result.metrics["cross_talk_overlap_ms"] is None
    assert result.metrics["yield_latency_ms"] != 0.0
    assert result.metrics["cross_talk_overlap_ms"] != 0.0


def test_source_timestamps_preserved_separately():
    """Verify target-reported source timestamp is preserved distinct from client timestamp."""
    ev = TraceEvent(
        timestamp_ms=500.0,
        event_type=EventType.TRANSCRIPT_FINAL,
        speaker_id="dr_aris",
        source_timestamp_ms=420.0,
        client_timestamp_ms=500.0,
        event_provenance="target_reported",
        is_simulated=False,
    )

    d = ev.to_dict()
    assert d["source_timestamp_ms"] == 420.0
    assert d["client_timestamp_ms"] == 500.0
    assert d["event_provenance"] == "target_reported"
    assert d["is_simulated"] is False
